WITH with_latest AS (SELECT s.id, s.opened_date, latest.order_amount FROM stores s LEFT JOIN LATERAL (SELECT c.amount AS order_amount FROM orders c WHERE c.store_id = s.id ORDER BY c.shipping_fee DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT CASE WHEN order_amount >= 1640 THEN 'PREMIUM' ELSE 'STANDARD' END AS order_amount_tier, COUNT(*) AS event_count, APPROX_PERCENTILE(order_amount, 0.9) AS order_amount_p90, APPROX_PERCENTILE(order_amount, 0.95) AS order_amount_p95 FROM with_latest GROUP BY order_amount_tier;
